import{_ as a,o as t,c as o,a0 as s}from"./chunks/framework.ChlVJx0I.js";const m=JSON.parse('{"title":"Llama refresh extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/llama-refresh.md","filePath":"extensions/llama-refresh.md","lastUpdated":1789709974000}'),r={name:"extensions/llama-refresh.md"};function l(i,e,n,h,d,c){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="llama-refresh-extension" tabindex="-1">Llama refresh extension <a class="header-anchor" href="#llama-refresh-extension" aria-label="Permalink to &quot;Llama refresh extension&quot;">​</a></h1><p>Self-heals the context window of a session that resolved a local llama.cpp model while the model was asleep.</p><p>A llama.cpp model reports its true context window only while it is loaded: an asleep model exposes no <code>n_ctx</code>, and the provider gives it a fixed 128000 (the Fallback window). A session that resolves the model while it is asleep keeps that window for its whole life, compacting far earlier than the model&#39;s real window requires, until a human re-selects the model by hand.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li>After each agent turn, if the active model is a llama.cpp model carrying the Fallback window and this model selection has not yet spent its Attempt, the extension forces a catalog refresh scoped to the llama.cpp provider, re-resolves the model, and re-applies it only when the window changed. The first request already woke the model, so the refresh sees the true <code>n_ctx</code>.</li><li>The repair costs at most one catalog refresh per model selection and at most one model change transcript entry per selection, and only when the window actually changed. A model genuinely loaded with a 128000 context is confirmed by the refresh and left untouched, so the check stays silent.</li><li>The refresh also persists the corrected catalog, so later sessions start corrected even when this session would not re-heal.</li><li>A refresh that fails (server down, aborted) is absorbed: the selection retries on the next turn end, so a down server degrades to today&#39;s behavior instead of erroring every turn.</li><li>Non-llama.cpp models are ignored entirely.</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The decision logic lives in the engine-free core module (<code>extensions/llama-refresh/refresh.ts</code>); the pi wiring (<code>index.ts</code>) only binds events and supplies the real dependencies (registry refresh, registry read-back, <code>pi.setModel</code>). See <a href="/pi-extensions/adr/0019-llama-refresh-self-heals-the-fallback-window.html">ADR 0019</a>.</p>',7)])])}const f=a(r,[["render",l]]);export{m as __pageData,f as default};
